import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createThrowingProvider(rejection: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw rejection;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('ChatOrchestrator coerces non-Error rejections', () => {
  it('coerces a string rejection to an Error before calling onError', async () => {
    let receivedError: Error | null = null;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createThrowingProvider('test error string'), promptBuilder, undefined, {
      hooks,
    });

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error propagates as-is
    }

    expect(receivedError).not.toBeNull();
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.message).toBe('test error string');
  });

  it('coerces a plain object rejection to an Error before calling onError', async () => {
    let receivedError: Error | null = null;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const rejectionObject = {code: 503, message: 'service unavailable'};
    const orchestrator = createChatOrchestrator(createThrowingProvider(rejectionObject), promptBuilder, undefined, {
      hooks,
    });

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error propagates as-is
    }

    expect(receivedError).not.toBeNull();
    expect(receivedError).toBeInstanceOf(Error);
    expect(typeof receivedError?.message).toBe('string');
    expect((receivedError?.message ?? '').length).toBeGreaterThan(0);
  });

  it('passes Error instances through unchanged', async () => {
    let receivedError: Error | null = null;
    const originalError = new Error('original error');

    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(createThrowingProvider(originalError), promptBuilder, undefined, {
      hooks,
    });

    try {
      await orchestrator.processMessage(createSession('hello'));
    } catch (error) {
      // Error propagates as-is
    }

    expect(receivedError).toBe(originalError);
  });
});

